import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>

__device__ __forceinline__ int floor_div_pos(int a, int b) {
    int q = a / b;
    int r = a % b;
    return (r < 0) ? (q - 1) : q;
}
template <typename scalar_t, typename acc_t>
__global__ void conv_transpose3d_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int64_t batch,
    int64_t in_channels,
    int64_t out_channels,
    int64_t in_depth,
    int64_t in_height,
    int64_t in_width,
    int64_t out_depth,
    int64_t out_height,
    int64_t out_width,
    int64_t kernel_size,
    int64_t stride,
    int64_t padding,
    int64_t groups,
    bool has_bias
) {
    constexpr int TILE_D = 4;
    constexpr int TILE_H = 8;
    constexpr int TILE_W = 8;
    constexpr int OC_TILE = 4;
    constexpr int SPATIAL_TILE = TILE_D * TILE_H * TILE_W;
    constexpr int THREADS = 128;
    const int in_c = static_cast<int>(in_channels);
    const int out_c = static_cast<int>(out_channels);
    const int in_d = static_cast<int>(in_depth);
    const int in_h = static_cast<int>(in_height);
    const int in_w = static_cast<int>(in_width);
    const int out_d = static_cast<int>(out_depth);
    const int out_h = static_cast<int>(out_height);
    const int out_w = static_cast<int>(out_width);
    const int k = static_cast<int>(kernel_size);
    const int s = static_cast<int>(stride);
    const int p = static_cast<int>(padding);
    const int gcount = static_cast<int>(groups);
    const int in_cpg = in_c / gcount;
    const int out_cpg = out_c / gcount;
    const int kernel_volume = k * k * k;
    const int tiles_h = (out_h + TILE_H - 1) / TILE_H;
    const int tiles_w = (out_w + TILE_W - 1) / TILE_W;
    const int tile_index = static_cast<int>(blockIdx.x);
    const int tile_d = tile_index / (tiles_h * tiles_w);
    const int tile_rem = tile_index % (tiles_h * tiles_w);
    const int tile_h = tile_rem / tiles_w;
    const int tile_w = tile_rem % tiles_w;
    const int n = static_cast<int>(blockIdx.z);
    const int oc_tiles_per_group = (out_cpg + OC_TILE - 1) / OC_TILE;
    const int group_tile = static_cast<int>(blockIdx.y);
    const int group = group_tile / oc_tiles_per_group;
    const int oc_tile = group_tile % oc_tiles_per_group;
    const int oc_base = oc_tile * OC_TILE;
    const bool active_oc0 = oc_base + 0 < out_cpg;
    const bool active_oc1 = oc_base + 1 < out_cpg;
    const bool active_oc2 = oc_base + 2 < out_cpg;
    const bool active_oc3 = oc_base + 3 < out_cpg;
    const int oc0 = group * out_cpg + oc_base + 0;
    const int oc1 = group * out_cpg + oc_base + 1;
    const int oc2 = group * out_cpg + oc_base + 2;
    const int oc3 = group * out_cpg + oc_base + 3;
    const int od_start = tile_d * TILE_D;
    const int oh_start = tile_h * TILE_H;
    const int ow_start = tile_w * TILE_W;
    const int od_end = min(out_d, od_start + TILE_D);
    const int oh_end = min(out_h, oh_start + TILE_H);
    const int ow_end = min(out_w, ow_start + TILE_W);
    const int id_start = max(0, floor_div_pos(od_start + p - (k - 1), s));
    const int ih_start = max(0, floor_div_pos(oh_start + p - (k - 1), s));
    const int iw_start = max(0, floor_div_pos(ow_start + p - (k - 1), s));
    const int id_end = min(in_d, floor_div_pos(od_end - 1 + p, s) + 1);
    const int ih_end = min(in_h, floor_div_pos(oh_end - 1 + p, s) + 1);
    const int iw_end = min(in_w, floor_div_pos(ow_end - 1 + p, s) + 1);
    const int shared_h = TILE_H + k - 1;
    const int shared_w = TILE_W + k - 1;
    const int shared_d_capacity = TILE_D + k - 1;
    const int64_t input_capacity =
        static_cast<int64_t>(shared_d_capacity) * shared_h * shared_w;
    extern __shared__ unsigned char shared_mem[];
    scalar_t* shared_input = reinterpret_cast<scalar_t*>(shared_mem);
    scalar_t* shared_weight = shared_input + input_capacity;
    const int tid = static_cast<int>(threadIdx.x);
    const int weight_count = in_cpg * OC_TILE * kernel_volume;
    for (int q = tid; q < weight_count; q += THREADS) {
        int v = q;
        const int kw = v % k;
        v /= k;
        const int kh = v % k;
        v /= k;
        const int kd = v % k;
        v /= k;
        const int oc_local = v % OC_TILE;
        const int ic_local = v / OC_TILE;
        scalar_t value = scalar_t(0);
        if (oc_base + oc_local < out_cpg) {
            const int weight_ic = group * in_cpg + ic_local;
            const int64_t weight_offset =
                (static_cast<int64_t>(weight_ic) * out_cpg +
                 oc_base + oc_local) * kernel_volume +
                (kd * k + kh) * k + kw;
            value = weight[weight_offset];
        }
        shared_weight[q] = value;
    }
    __syncthreads();
    acc_t sum0[2] = {acc_t(0), acc_t(0)};
    acc_t sum1[2] = {acc_t(0), acc_t(0)};
    acc_t sum2[2] = {acc_t(0), acc_t(0)};
    acc_t sum3[2] = {acc_t(0), acc_t(0)};
    if (has_bias) {
        if (active_oc0) { sum0[0] = sum0[1] = static_cast<acc_t>(bias[oc0]); }
        if (active_oc1) { sum1[0] = sum1[1] = static_cast<acc_t>(bias[oc1]); }
        if (active_oc2) { sum2[0] = sum2[1] = static_cast<acc_t>(bias[oc2]); }
        if (active_oc3) { sum3[0] = sum3[1] = static_cast<acc_t>(bias[oc3]); }
    }
    const int shared_d = max(0, id_end - id_start);
    const int shared_h_actual = max(0, ih_end - ih_start);
    const int shared_w_actual = max(0, iw_end - iw_start);
    const int shared_count = shared_d * shared_h_actual * shared_w_actual;
    for (int ic_local = 0; ic_local < in_cpg; ++ic_local) {
        const int ic = group * in_cpg + ic_local;
        for (int q = tid; q < shared_count; q += THREADS) {
            int v = q;
            const int iw_local = v % shared_w_actual;
            v /= shared_w_actual;
            const int ih_local = v % shared_h_actual;
            v /= shared_h_actual;
            const int id_local = v;
            const int input_d = id_start + id_local;
            const int input_h = ih_start + ih_local;
            const int input_w = iw_start + iw_local;
            const int64_t x_offset =
                (((static_cast<int64_t>(n) * in_c + ic) * in_d + input_d) * in_h +
                 input_h) * in_w + input_w;
            const int64_t smem_offset =
                (static_cast<int64_t>(id_local) * shared_h + ih_local) *
                shared_w + iw_local;
            shared_input[smem_offset] = x[x_offset];
        }
        __syncthreads();
        for (int pass = 0; pass < 2; ++pass) {
            const int spatial = tid + pass * THREADS;
            if (spatial >= SPATIAL_TILE) continue;
            const int local_d = spatial / (TILE_H * TILE_W);
            const int local_h = (spatial / TILE_W) % TILE_H;
            const int local_w = spatial % TILE_W;
            const int od = od_start + local_d;
            const int oh = oh_start + local_h;
            const int ow = ow_start + local_w;
            if (od >= out_d || oh >= out_h || ow >= out_w) continue;
            for (int kd = 0; kd < k; ++kd) {
                const int d_num = od + p - kd;
                if (d_num < 0 || d_num % s != 0) continue;
                const int id = d_num / s;
                if (id < id_start || id >= id_end || id >= in_d) continue;
                for (int kh = 0; kh < k; ++kh) {
                    const int h_num = oh + p - kh;
                    if (h_num < 0 || h_num % s != 0) continue;
                    const int ih = h_num / s;
                    if (ih < ih_start || ih >= ih_end || ih >= in_h) continue;
                    for (int kw = 0; kw < k; ++kw) {
                        const int w_num = ow + p - kw;
                        if (w_num < 0 || w_num % s != 0) continue;
                        const int iw = w_num / s;
                        if (iw < iw_start || iw >= iw_end || iw >= in_w) continue;
                        const int kernel_offset = (kd * k + kh) * k + kw;
                        const int64_t input_offset =
                            (static_cast<int64_t>(id - id_start) * shared_h +
                             (ih - ih_start)) * shared_w + (iw - iw_start);
                        const acc_t input_value = static_cast<acc_t>(shared_input[input_offset]);
                        const int weight_base = ic_local * OC_TILE * kernel_volume + kernel_offset;
                        if (active_oc0) sum0[pass] += input_value * static_cast<acc_t>(shared_weight[weight_base]);
                        if (active_oc1) sum1[pass] += input_value * static_cast<acc_t>(shared_weight[weight_base + kernel_volume]);
                        if (active_oc2) sum2[pass] += input_value * static_cast<acc_t>(shared_weight[weight_base + 2 * kernel_volume]);
                        if (active_oc3) sum3[pass] += input_value * static_cast<acc_t>(shared_weight[weight_base + 3 * kernel_volume]);
                    }
                }
            }
        }
        __syncthreads();
    }
    for (int pass = 0; pass < 2; ++pass) {
        const int spatial = tid + pass * THREADS;
        if (spatial >= SPATIAL_TILE) continue;
        const int od = od_start + spatial / (TILE_H * TILE_W);
        const int oh = oh_start + (spatial / TILE_W) % TILE_H;
        const int ow = ow_start + spatial % TILE_W;
        if (od >= out_d || oh >= out_h || ow >= out_w) continue;
        if (active_oc0) {
            const int64_t offset = (((static_cast<int64_t>(n) * out_c + oc0) * out_d + od) * out_h + oh) * out_w + ow;
            output[offset] = static_cast<scalar_t>(sum0[pass]);
        }
        if (active_oc1) {
            const int64_t offset = (((static_cast<int64_t>(n) * out_c + oc1) * out_d + od) * out_h + oh) * out_w + ow;
            output[offset] = static_cast<scalar_t>(sum1[pass]);
        }
        if (active_oc2) {
            const int64_t offset = (((static_cast<int64_t>(n) * out_c + oc2) * out_d + od) * out_h + oh) * out_w + ow;
            output[offset] = static_cast<scalar_t>(sum2[pass]);
        }
        if (active_oc3) {
            const int64_t offset = (((static_cast<int64_t>(n) * out_c + oc3) * out_d + od) * out_h + oh) * out_w + ow;
            output[offset] = static_cast<scalar_t>(sum3[pass]);
        }
    }
}
template <typename scalar_t>
at::Tensor conv_transpose3d_cuda_impl(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups
) {
    const auto batch = x.size(0);
    const auto in_channels = x.size(1);
    const auto in_depth = x.size(2);
    const auto in_height = x.size(3);
    const auto in_width = x.size(4);

    const auto kernel_size = weight.size(2);
    const auto out_channels_per_group = weight.size(1);
    const auto out_channels = out_channels_per_group * groups;

    const auto out_depth =
        (in_depth - 1) * stride - 2 * padding + kernel_size + output_padding;
    const auto out_height =
        (in_height - 1) * stride - 2 * padding + kernel_size + output_padding;
    const auto out_width =
        (in_width - 1) * stride - 2 * padding + kernel_size + output_padding;

    auto output = at::empty(
        {batch, out_channels, out_depth, out_height, out_width},
        x.options());

    const int64_t tiles_d = (out_depth + 4 - 1) / 4;
    const int64_t tiles_h = (out_height + 8 - 1) / 8;
    const int64_t tiles_w = (out_width + 8 - 1) / 8;
    const int64_t tile_count = tiles_d * tiles_h * tiles_w;
    const int64_t oc_tiles_per_group =
        (out_channels_per_group + 4 - 1) / 4;
    const scalar_t* bias_ptr = nullptr;
    bool has_bias = false;
    if (bias.has_value() && bias->defined()) {
        bias_ptr = bias->data_ptr<scalar_t>();
        has_bias = true;
    }
    const int64_t channel_tile_count =
        groups * oc_tiles_per_group;
    constexpr int threads = 128;
    const dim3 blocks(
        static_cast<unsigned int>(tile_count),
        static_cast<unsigned int>(channel_tile_count),
        static_cast<unsigned int>(batch));
    const int64_t input_smem_elements =
         (4 + kernel_size - 1) *
        (8 + kernel_size - 1) *
        (8 + kernel_size - 1);
    const int64_t in_channels_per_group = in_channels / groups;
    const int64_t kernel_volume =
        kernel_size * kernel_size * kernel_size;
    const int64_t weight_smem_elements =
         (in_channels_per_group * 4 * kernel_volume);
    const size_t smem_bytes = static_cast<size_t>(
        input_smem_elements + weight_smem_elements) * sizeof(scalar_t);

    auto stream = at::cuda::getCurrentCUDAStream();
    using acc_t = at::acc_type<scalar_t, true>;

    conv_transpose3d_kernel<scalar_t, acc_t>
        <<<blocks, threads, smem_bytes, stream>>>(
            x.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            bias_ptr,
            output.data_ptr<scalar_t>(),
            batch,
            in_channels,
            out_channels,
            in_depth,
            in_height,
            in_width,
            out_depth,
            out_height,
            out_width,
            kernel_size,
            stride,
            padding,
            groups,
            has_bias);

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}

at::Tensor conv_transpose3d_cuda(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 5, "x must be 5-dimensional");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5-dimensional");
    TORCH_CHECK(stride > 0, "stride must be positive");
    TORCH_CHECK(padding >= 0, "padding must be non-negative");
    TORCH_CHECK(output_padding >= 0, "output_padding must be non-negative");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(x.size(1) % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(weight.size(0) == x.size(1),
                "weight input-channel dimension mismatch");
    TORCH_CHECK(weight.size(2) == weight.size(3) &&
                    weight.size(3) == weight.size(4),
                "only square kernels are supported");
    TORCH_CHECK(output_padding < stride,
                "output_padding must be smaller than stride");

    if (bias.has_value() && bias->defined()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias->numel() == weight.size(1) * groups,
                    "bias dimension mismatch");
    }

    auto x_contig = x.contiguous();
    auto weight_contig = weight.contiguous();

    c10::optional<at::Tensor> bias_contig = c10::nullopt;
    if (bias.has_value() && bias->defined()) {
        bias_contig = bias->contiguous();
    }
    TORCH_CHECK(
        weight_contig.scalar_type() == x_contig.scalar_type(),
        "x and weight must have the same dtype");
    if (bias_contig.has_value()) {
        TORCH_CHECK(
            bias_contig->scalar_type() == x_contig.scalar_type(),
            "x and bias must have the same dtype");
    }


    at::Tensor result;
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        x_contig.scalar_type(),
        "conv_transpose3d_cuda",
        [&] {
            result = conv_transpose3d_cuda_impl<scalar_t>(
                x_contig,
                weight_contig,
                bias_contig,
                stride,
                padding,
                output_padding,
                groups);
        });

    return result;
}
"""

_cpp_src = r"""
#include <torch/extension.h>
at::Tensor conv_transpose3d_cuda(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups
);
at::Tensor conv_transpose3d(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups
) {
    return conv_transpose3d_cuda(
        x, weight, bias, stride, padding, output_padding, groups);
}
"""

_conv_transpose3d_ext = load_inline(
    name="custom_conv_transpose3d_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv_transpose3d"],
    extra_cuda_cflags=["-O3"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv_transpose3d_ext.conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            self.conv_transpose3d.bias,
            self.conv_transpose3d.stride[0],
            self.conv_transpose3d.padding[0],
            self.conv_transpose3d.output_padding[0],
            self.conv_transpose3d.groups,
        )

