import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>

template <typename scalar_t, typename acc_t>
__global__ void conv_transpose3d_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int64_t batch,
    int64_t in_channels,
    int64_t out_channels,
    int64_t in_depth,
    int64_t in_height,
    int64_t in_width,
    int64_t out_depth,
    int64_t out_height,
    int64_t out_width,
    int64_t kernel_size,
    int64_t stride,
    int64_t padding,
    int64_t groups,
    bool has_bias
) {
    constexpr int TILE_D = 4;
    constexpr int TILE_H = 8;
    constexpr int TILE_W = 8;
    constexpr int OC_TILE = 4;

    const int in_channels_i = static_cast<int>(in_channels);
    const int out_channels_i = static_cast<int>(out_channels);
    const int in_depth_i = static_cast<int>(in_depth);
    const int in_height_i = static_cast<int>(in_height);
    const int in_width_i = static_cast<int>(in_width);
    const int out_depth_i = static_cast<int>(out_depth);
    const int out_height_i = static_cast<int>(out_height);
    const int out_width_i = static_cast<int>(out_width);
    const int kernel_size_i = static_cast<int>(kernel_size);
    const int stride_i = static_cast<int>(stride);
    const int padding_i = static_cast<int>(padding);
    const int groups_i = static_cast<int>(groups);

    const int out_channels_per_group = out_channels_i / groups_i;
    const int in_channels_per_group = in_channels_i / groups_i;
    const int kernel_volume = kernel_size_i * kernel_size_i * kernel_size_i;
    const int tiles_h = (out_height_i + TILE_H - 1) / TILE_H;
    const int tiles_w = (out_width_i + TILE_W - 1) / TILE_W;

    const int tile_index = static_cast<int>(blockIdx.x);
    const int tile_d = tile_index / (tiles_h * tiles_w);
    const int tile_rem = tile_index % (tiles_h * tiles_w);
    const int tile_h = tile_rem / tiles_w;
    const int tile_w = tile_rem % tiles_w;
    const int n = static_cast<int>(blockIdx.z);

    const int oc_tiles_per_group =
        (out_channels_per_group + OC_TILE - 1) / OC_TILE;
    const int group_tile = static_cast<int>(blockIdx.y);
    const int group = group_tile / oc_tiles_per_group;
    const int oc_tile = group_tile % oc_tiles_per_group;
    const int oc_local = oc_tile * OC_TILE + (static_cast<int>(threadIdx.x) % OC_TILE);
    const bool active_oc = oc_local < out_channels_per_group;
    const int oc = group * out_channels_per_group + oc_local;

    const int od_start = tile_d * TILE_D;
    const int oh_start = tile_h * TILE_H;
    const int ow_start = tile_w * TILE_W;
    const int od_end = min(out_depth_i, od_start + TILE_D);
    const int oh_end = min(out_height_i, oh_start + TILE_H);
    const int ow_end = min(out_width_i, ow_start + TILE_W);

    const int d_num = od_start + padding_i - (kernel_size_i - 1);
    const int h_num = oh_start + padding_i - (kernel_size_i - 1);
    const int w_num = ow_start + padding_i - (kernel_size_i - 1);
    const int id_start = max(0, d_num / stride_i);
    const int ih_start = max(0, h_num / stride_i);
    const int iw_start = max(0, w_num / stride_i);

    const int id_end = min(in_depth_i, (od_end - 1 + padding_i) / stride_i + 1);
    const int ih_end = min(in_height_i, (oh_end - 1 + padding_i) / stride_i + 1);
    const int iw_end = min(in_width_i, (ow_end - 1 + padding_i) / stride_i + 1);

    const int shared_height = TILE_H + kernel_size_i - 1;
    const int shared_width = TILE_W + kernel_size_i - 1;

    extern __shared__ unsigned char shared_mem[];
    scalar_t* shared_input = reinterpret_cast<scalar_t*>(shared_mem);
    const int shared_depth_capacity = TILE_D + kernel_size_i - 1;
